head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[dataList > M > setRowPosition]<br/>Row 의 인덱스값을 사용하여 DataList 모듈의 특정 Row 를 선택합니다.",
    "validation" : [
        "GridView 에서 setFocusedCell() 등의 메소드 또는 사용자에 의해 포커스된 Row 가 변경되면 DataList 모듈의 선택 Row 에 반영됩니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {   
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        $p.data.remove("target1");
    }

    if (typeof gridView1 !== 'undefined') {
        gridView1.remove();
    }    

    // // 조건 설정       
    // let properties = {

    // };

    // let cList = $c.gcm.createCList(properties);

    // // 이벤트 설정
    // let eList = $c.gcm.createEList([""]);       

    // target 생성
    $c.gcm.createBasicDataList();

    // event 바인딩    
    target1.bind("onrowpositionchange", function(e){ wf_body_bottom.getObj("scwin").setReturnValue("=====onrowpositionchange=====");});

    // gridView 생성
    $c.gcm.createBasicGridView('dataList="data:target1" rowStatusVisible="true" focusMode="row" syncRowPositionOption="style" ev:oncellclick="scwin.gridView1_oncellclick"', '', 'gridView1');
}


scwin.gridView1_oncellclick = function (rowIndex, columnIndex, columnId) {
    scwin.btn_getRowPosition_onclick();
}



scwin.btn_getRowPosition_onclick = function (e) {
    let rtn = target1.getRowPosition();

    wf_body_bottom.getObj("scwin").setReturnValue("getRowPosition: " + rtn);
};



scwin.btn_setFocusedCell_onclick = function (e) {
	gridView1.setFocusedCell(0, "col1", false);

    scwin.btn_getRowPosition_onclick();
};
